"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

// Toggle: generated by UIX from the design system. Same variants and sizes as the Figma component.

const toggleVariants = cva(
  "inline-flex shrink-0 cursor-pointer items-center justify-center whitespace-nowrap transition-colors focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus disabled:pointer-events-none disabled:text-fg-disabled [&_svg]:shrink-0 rounded-md",
  {
    variants: {
      variant: {
        default: "",
        outline: "border",
      },
      pressed: {
        false: "text-fg-secondary hover:bg-subtle hover:text-fg-primary",
        true: "bg-muted text-fg-primary",
      },
      size: {
        sm: "h-8 px-2 gap-1-5 text-label-small [&_svg]:size-4",
        md: "h-10 px-3 gap-2 text-label-medium [&_svg]:size-5",
      },
    },
    compoundVariants: [
      { variant: "outline", pressed: false, class: "border-line-default" },
      { variant: "outline", pressed: true, class: "border-line-strong" },
    ],
    defaultVariants: {
      variant: "default",
      size: "md",
    },
  },
);

export interface ToggleProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof toggleVariants> {
  /** Start pressed (uncontrolled). Pass the variant prop "pressed" to control it. */
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  /** Icon before the label. */
  icon?: React.ReactNode;
}

const Toggle = React.forwardRef<HTMLButtonElement, ToggleProps>(
  ({ className, variant, pressed, size, defaultPressed = false, onPressedChange, onClick, icon, children, ...props }, ref) => {
    const [inner, setInner] = React.useState(defaultPressed);
    const on = pressed ?? inner;
    return (
      <button data-slot="toggle" data-kind="control" ref={ref} type="button" aria-pressed={on} {...props} onClick={(event) => {
        onClick?.(event);
        setInner(!on);
        onPressedChange?.(!on);
      }} className={cn(toggleVariants({ variant, pressed: on, size }), className)}>
        {icon}
        {children}
      </button>
    );
  },
);
Toggle.displayName = "Toggle";

export interface ToggleGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Joins the toggles into one bar that shares a hairline (use the outline variant). */
  attached?: boolean;
}

const ToggleGroup = React.forwardRef<HTMLDivElement, ToggleGroupProps>(({ className, attached = false, ...props }, ref) => (
  <div ref={ref} role="group" className={cn("inline-flex items-center gap-1", attached && "gap-0 -space-x-px overflow-hidden rounded-md [&>*]:rounded-none", className)} {...props} />
));
ToggleGroup.displayName = "ToggleGroup";

export { Toggle, ToggleGroup, toggleVariants };
